args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel ?motherBirthPlace ?motherBirthPlaceLabel WHERE {
  dbr:Berengaria_of_Portugal dbp:mother ?mother .
  OPTIONAL { ?mother dbo:birthPlace ?motherBirthPlace . }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
  OPTIONAL { ?motherBirthPlace rdfs:label ?motherBirthPlaceLabel . FILTER(lang(?motherBirthPlaceLabel) = 'en') }
}

